            //    {
            //        "code":0,
            //        "msg":"",
            //        "data":[
            //          {
            //            "symbol": "BTC-USDT",
            //            "fundingRate": "0.0001",
            //            "fundingTime": 1585684800000
            //          },
            //          ...
            //        ]
            //    }
            //
            List<Object> data = (List<Object>) this.safeList(response, "data", new ArrayList<Object>(Arrays.asList()));
            return this.parseFundingRateHistories(data, market, since, limit);
