    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        // mark price
        // {
        //     "symbol": "string",
        //     "lastFundingRate": "string",
        //     "markPrice": "string",
        //     "indexPrice": "string",
        //     "nextFundingTime": "int64"
        // }
        //
        // spot
        //    {
        //        "symbol": "BTC-USDT",
        //        "openPrice": "26032.08",
        //        "highPrice": "26178.86",
        //        "lowPrice": "25968.18",
        //        "lastPrice": "26113.60",
        //        "volume": "1161.79",
        //        "quoteVolume": "30288466.44",
        //        "openTime": "1693081020762",
        //        "closeTime": "1693167420762",
        //  added 2023-11-10:
        //        "bidPrice": 16726.0,
        //        "bidQty": 0.05,
        //        "askPrice": 16726.0,
        //        "askQty": 0.05,
        //    }
        // swap
        //
        //    {
        //        "symbol": "BTC-USDT",
        //        "priceChange": "52.5",
        //        "priceChangePercent": "0.31%", // they started to add the percent sign in value
        //        "lastPrice": "16880.5",
        //        "lastQty": "2.2238",          // only present in swap!
        //        "highPrice": "16897.5",
        //        "lowPrice": "16726.0",
        //        "volume": "245870.1692",
        //        "quoteVolume": "4151395117.73",
        //        "openPrice": "16832.0",
        //        "openTime": 1672026667803,
        //        "closeTime": 1672026648425,
        //  added 2023-11-10:
        //        "bidPrice": 16726.0,
        //        "bidQty": 0.05,
        //        "askPrice": 16726.0,
        //        "askQty": 0.05,
        //    }
        //
        String marketId = this.safeString(ticker, "symbol");
        String lastQty = this.safeString(ticker, "lastQty");
        // in spot markets, lastQty is not present
        // it's (bad, but) the only way we can check the tickers origin
        String type = (((java.util.Objects.equals(lastQty, null)))) ? "spot" : "swap";
        market = (Map<String, Object>) (this.safeMarket(marketId, market, null, type));
        String symbol = (String) ((Map<String, Object>)market).get("symbol");
        String open = this.safeString(ticker, "openPrice");
        String high = this.safeString(ticker, "highPrice");
        String low = this.safeString(ticker, "lowPrice");
        String close = this.safeString(ticker, "lastPrice");
        String quoteVolume = this.safeString(ticker, "quoteVolume");
        String baseVolume = this.safeString(ticker, "volume");
        String percentage = this.safeString(ticker, "priceChangePercent");
        if (!java.util.Objects.equals(percentage, null))
        {
            percentage = Helpers.replace(percentage, (String)"%", (String)"");
        }
        String change = this.safeString(ticker, "priceChange");
        Long ts = this.safeInteger(ticker, "closeTime");
        if ((ts != null && ts == 0))
        {
            ts = null;
        }
        String datetime = this.iso8601(ts);
        String bid = this.safeString(ticker, "bidPrice");
        String bidVolume = this.safeString(ticker, "bidQty");
        String ask = this.safeString(ticker, "askPrice");
        String askVolume = this.safeString(ticker, "askQty");
        final Long finalTs = ts;
        final String finalPercentage = percentage;
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", finalTs );
            put( "datetime", datetime );
            put( "high", high );
            put( "low", low );
            put( "bid", bid );
            put( "bidVolume", bidVolume );
            put( "ask", ask );
            put( "askVolume", askVolume );
            put( "vwap", null );
            put( "open", open );
            put( "close", close );
            put( "last", null );
            put( "previousClose", null );
            put( "change", change );
            put( "percentage", finalPercentage );
            put( "average", null );
            put( "baseVolume", baseVolume );
            put( "quoteVolume", quoteVolume );
            put( "markPrice", Bingx.this.safeString(ticker, "markPrice") );
            put( "indexPrice", Bingx.this.safeString(ticker, "indexPrice") );
            put( "info", ticker );
        }}, market);
    }
    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        return this.parseTicker(ticker, Helpers.getArgMap(optionalArgs, 0, null));
    }

